"""Reconcile longitudinal planning with scoped later qualification evidence."""
from pathlib import Path
import json,hashlib
P=Path('docs/planning');B=P/'campaign3-history-universe-rev1';O=P/'campaign3-history-longitudinal-plans-rev1'
def load(p):return json.loads(Path(p).read_text(encoding='utf-8-sig'))
def ref(p):return dict(path=Path(p).as_posix(),sha256=hashlib.sha256(Path(p).read_bytes()).hexdigest())
def save(n,v):
 p=O/n
 if p.exists():assert load(p)==v,p
 else:p.write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8',newline='\n')
notes={'docs/planning/LONGITUDINAL_GOAL_EXECUTION_CHECKPOINT.md': 'Historical capture only:20 trajectories/340 captured prefix hashes and zero restored checks; not completed replay. Required120 trajectories/2040 restores,1920 advancing/120 terminal, later explicitly completed by goal qualification. Old session identifiers are historical, not live handles or restart authority. Authenticate immutable plan/run/source and preserve orphan archives before reuse. Zero acquired standing differs from nonzero standing rounded to zero. Prior8 focused/328 reference receipts reverified, not rerun. Native source plus component receiving does not qualify one joined native scheduler.', 'docs/planning/LONGITUDINAL_GOAL_INTERIM_REVIEW.md': 'Historical72-trajectory subset does not replace120-run/2040-restore gate. Preserve18/24 probability and14/24 action differences, six zero-standing equalities and four stochastic action equalities despite changed probabilities. Goal withdrawal/replacement changes8/8 later sequences without changing17 source hashes or old goal identity.24 KeepAll/expiry equalities are receiver-specific, not memory reduction. NoFeedback and GoalEqualsOpportunity were unreviewed here; later full goal qualification supplies their scoped comparison. Fine1/16 remains candidate; no universal calibration or fresh replay inferred.', 'docs/planning/LONGITUDINAL_INTEGRATION_READINESS.md': 'Historical joined-goal/routine/habit/loss gaps route to four later bounded component qualifications. Actually acquired biography and independently adopted goals must precede later choice; authored standing is not acquisition. Preserve maintained/replaced/retired and NoFeedback controls, original meaning, actor lineage and immediate-successor replay. Later evidence does not turn component ownership into joined native admission. Schedule is not routine, practice is not habit and episode expiry is not personal loss. Affect dimensionality remains a separate reduction obligation, not settled by these integrations.', 'docs/planning/LONGITUDINAL_ROUTINE_READINESS.md': 'Earlier goal receiver starts14 and cannot establish resumed practice. Later routine qualification adds six actual practices before interruption, outcome history, corrected belief, cue intervention and current goals; restored opportunity alone is insufficient. Scheduled availability does not guarantee action: preserved seed0 skips14 and resumes15. Native source skill/social episode expiry is not forgetting receiving practice episodes; later habit qualification separately supplies practice ownership. Source reuse must be prospectively authenticated and not counted as fresh native restores. No natural scheduling, general recognition or single native join follows.', 'docs/planning/LONGITUDINAL_HABIT_RELEARNING_READINESS.md': 'Routine negative performance feedback63/64 to63/128 removes availability under candidate1/2 threshold; not relearning or physiological recovery. Later habit REV2 supplies separately owned actual practice episodes, recency displacement versus KeepAll, inhibition/release, actual renewed18/19 practice and positive outcomes, then corrected-belief free probes. Hidden/unavailable practice with identical reports does not relearn. All8 restore availability but only4 act in final probes. Local episode content loss is not global erasure: full fold journal/audit survives; Stored/Derived both retain diagnostic cache. Original failed harness cohorts retained and excluded from new counts. No cache-free necessity, compressed history or native admission claim.', 'docs/planning/LONGITUDINAL_PERSONAL_LOSS_READINESS.md': 'Personal loss requires acquired prior value and admitted evidence; not expiry, failed practice or absent opportunity. Later valued-contact component acquires two participations and authored goal adoption, then separates physical availability/report/belief/appraisal/choice/execution. HiddenLoss/NoLoss and false/reported loss preserve cognitive equalities; masked outcomes do not teach recovery. Original positive relationship history and goal remain until explicit withdrawal. Later480 runs/6240 component prefixes are not public Save132. Death, clinical grief, autonomous attachment formation and permanent recovery remain outside scope. Support reads final affect coordinate, so this experiment does not prove two-coordinate necessity.'}
ip=P/'campaign3-history-source-roles-rev249/index.json';ix=load(ip);entries={e['path']:e for e in load(B/'manifest.json')['entries']}
chain=[ref(P/n) for n in ['CAMPAIGN3_LONGITUDINAL_GOAL_QUALIFICATION.md','CAMPAIGN3_LONGITUDINAL_ROUTINE_QUALIFICATION.md','CAMPAIGN3_LONGITUDINAL_HABIT_QUALIFICATION.md','CAMPAIGN3_LONGITUDINAL_PERSONAL_LOSS_QUALIFICATION.md']]
sources=[]
for p,n in notes.items():
 assert p in ix['unassignedCandidatePaths'] and ref(p)['sha256']==entries[p]['sha256']
 sources.append(dict(**ref(p),role='HISTORICAL LONGITUDINAL PLAN WITH SCOPED LATER COMPLETION',judgment=n,acceptanceChain=chain))
rows=[]
with (B/'units.jsonl').open(encoding='utf-8') as f:
 for line in f:
  u=json.loads(line)
  if u['source'] not in notes:continue
  assert u['sourceSha256']==entries[u['source']]['sha256']
  rows.append(dict(occurrenceId=u['id'],source=u['source'],sourceSha256=u['sourceSha256'],location=u['location'],text=u['text'],category='NARRATIVE'))
assert len({r['occurrenceId'] for r in rows})==len(rows)
O.mkdir(exist_ok=True)
save('review.json',dict(status='SIX LONGITUDINAL PLANS RECONCILED',checker=ref(__file__),sourceIndex=ref(ip),sourceRoles=sources,rows=rows,preservedArtifacts=[],limits=['Planning and captured hashes do not establish completed replay; later qualifications preserve component/native distinctions.','Later bounded completion supersedes routing only within named profiles, not all ideal-loop phenomena.','No runtime/test/build rerun, source gap closure, law/model/verdict/corpus/obligation status change or historical adequacy claim.'],obligations=['RO-C3-008','RO-C3-019','RO-C3-020','RO-C3-021']))
save('check.json',dict(status='PASS LONGITUDINAL PLANNING HISTORY',sources=len(sources),originalNarrativeOccurrences=len(rows),originalBackingOccurrences=0,review=ref(O/'review.json')))
print(json.dumps(load(O/'check.json')))
